package search

import "strings"

// AppAlias 从应用 ID 里抽一个"产品名"，代替 Path 参与模糊匹配。
//
// 不能直接把应用的 Path 交给匹配器：它是 shell:AppsFolder\<ID> 或磁盘路径，
// 而"路径包含"这一档会把路径中间的**任意子串**都算命中。实测搜 cal 时，
// C:\Users\…\AppData\Local\nvm\nvm.exe 里的 "Local" 含 cal（Lo-cal），
// 于是 nvm、Python 3.11/3.12/3.14 全冒出来，真正的计算器反被挤到第四。
// 这里只取最后一段（exe 名或 AUMID），去掉 !App 后缀、发布哈希和可执行扩展名。
func AppAlias(id string) string {
	s := id
	if i := strings.LastIndexAny(s, `\/`); i >= 0 {
		s = s[i+1:]
	}
	if i := strings.Index(s, "!"); i >= 0 {
		s = s[:i]
	}
	// 自动生成的 AUMID（Microsoft.AutoGenerated.{6620B45B-…}）里只剩一串随机十六进制，
	// 拿它参与模糊匹配只会制造噪声（"nvm" 能在这串字母里凑出子序列）。
	if strings.ContainsAny(s, "{}") {
		return ""
	}
	low := strings.ToLower(s)
	for _, ext := range []string{".exe", ".lnk", ".bat", ".cmd", ".msc", ".com"} {
		if strings.HasSuffix(low, ext) {
			s = s[:len(s)-len(ext)]
			break
		}
	}
	// 包名后面挂的发布哈希：Microsoft.WindowsCalculator_8wekyb3d8bbwe
	if i := strings.LastIndex(s, "_"); i >= 0 && len(s)-(i+1) >= 8 {
		s = s[:i]
	}
	s = strings.Map(func(r rune) rune {
		switch r {
		case '.', '_', '-':
			return ' '
		}
		return r
	}, s)
	// AUMID 常把产品名重复一遍（WorkBuddy.WorkBuddy）：重复的段留在别名里
	// 会让 "kk" 这种查询把它当成散落子序列命中，按段去重。
	fields := strings.Fields(s)
	kept := fields[:0]
	for i, f := range fields {
		if i > 0 && strings.EqualFold(f, fields[i-1]) {
			continue
		}
		kept = append(kept, f)
	}
	return strings.Join(kept, " ")
}
